const body = $input.first().json.body || $input.first().json;

const adType     = (body.ad_type     || '').toLowerCase().trim();
const entityUuid = (body.entity_uuid || '').trim();
const leadName   = (body.lead_name   || 'Valued Customer').trim();
const phone      = (body.phone       || '').replace(/\s+/g, '').trim();
const country    = (body.country     || 'SA').toUpperCase().trim();
const email      = (body.email       || '').trim();

if (!['listing', 'project'].includes(adType))
  throw new Error('ad_type must be listing or project. Got: ' + adType);
if (!entityUuid)
  throw new Error('entity_uuid is required');
if (!phone)
  throw new Error('phone is required');

// Country → IANA timezone map for calling-hours check
const tzMap = {
  SA: 'Asia/Riyadh',   AE: 'Asia/Dubai',    KW: 'Asia/Kuwait',
  BH: 'Asia/Bahrain',  QA: 'Asia/Qatar',    OM: 'Asia/Muscat',
  EG: 'Africa/Cairo',  JO: 'Asia/Amman',    LB: 'Asia/Beirut',
  IQ: 'Asia/Baghdad',  YE: 'Asia/Aden',     PK: 'Asia/Karachi',
  IN: 'Asia/Kolkata',  DEFAULT: 'Asia/Riyadh'
};
const timezone = tzMap[country] || tzMap.DEFAULT;

const now = new Date();
const localHour = parseInt(
  now.toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: timezone })
);
const isCallableNow = localHour >= 9 && localHour < 21;

return [{
  json: {
    adType, entityUuid, leadName, phone, country, email,
    timezone, isCallableNow,
    receivedAt: now.toISOString(),
    retryCount: parseInt(body.retry_count || '0'),
    crmLeadId:  body.crm_lead_id || null
  }
}];

const data  = $input.first().json;
const retry = data.retryCount || 0;
const next  = new Date();
next.setDate(next.getDate() + (retry === 0 ? 0 : retry));
// Set to 9:00 AM next callable day (caller must re-trigger at this time via their scheduler)
next.setHours(9, 0, 0, 0);
return [{
  json: {
    ...data,
    action:       'SCHEDULED_LATER',
    scheduledAt:  next.toISOString(),
    reason:       'Outside calling hours (9am-9pm ' + data.timezone + ')'
  }
}];

const input   = $('Extract & Validate Input').first().json;
const adType  = input.adType;

let propertyContext = '';
let propertyName    = '';
let priceRange      = '';
let propertyCity    = '';

// ── Build context block based on ad type ──
if (adType === 'listing') {
  const row = $('Fetch Listing Details').first().json;
  if (!row || !row.id)
    throw new Error('Listing not found or inactive: ' + input.entityUuid);

  propertyName = row.en_title || row.ar_title || 'the property';
  priceRange   = row.price
    ? 'SAR ' + (row.price / 1_000_000).toFixed(2) + 'M'
    : 'Price on request';
  propertyCity = row.city || '';

  propertyContext = [
    '=== PROPERTY YOU ARE CALLING ABOUT ===',
    'Type: Individual Listing',
    'Name: ' + propertyName,
    'Location: ' + [row.district, row.city].filter(Boolean).join(', '),
    'Price: ' + priceRange,
    'Area: ' + (row.area_sqm || 'N/A') + ' sqm',
    'Bedrooms: ' + (row.bedrooms  || 'N/A'),
    'Bathrooms: ' + (row.bathrooms || 'N/A'),
    'Completion: ' + (row.completion_status || 'N/A'),
    row.project_name_en ? 'Part of Project: ' + row.project_name_en : '',
    row.description_en  ? 'Details: ' + row.description_en.substring(0, 400) : '',
    '======================================',
  ].filter(Boolean).join('\n');

} else {
  const row = $('Fetch Project + Layouts').first().json;
  if (!row || !row.project_id)
    throw new Error('Project not found: ' + input.entityUuid);

  propertyName = row.name_en || row.name_ar || 'the project';
  propertyCity = row.city || '';

  const minP = row.min_price ? 'SAR ' + (row.min_price / 1_000_000).toFixed(2) + 'M' : 'N/A';
  const maxP = row.max_price ? 'SAR ' + (row.max_price / 1_000_000).toFixed(2) + 'M' : 'N/A';
  priceRange = minP + ' – ' + maxP;

  let layouts = [];
  try {
    layouts = Array.isArray(row.layouts)
      ? row.layouts
      : JSON.parse(row.layouts || '[]');
  } catch(e) { layouts = []; }

  const layoutLines = layouts.length > 0
    ? layouts.slice(0, 8).map((l, i) => {
        const p = l.price ? 'SAR ' + (l.price / 1_000_000).toFixed(2) + 'M' : 'TBD';
        return `  ${i + 1}. ${l.title || 'Unit'}: ${l.bedrooms || 'N/A'} BR | ${l.area_sqm || 'N/A'} sqm | ${p} | ${l.completion_status || 'N/A'}`;
      }).join('\n')
    : '  No layout data available';

  propertyContext = [
    '=== PROPERTY YOU ARE CALLING ABOUT ===',
    'Type: Compound / Project',
    'Name: ' + propertyName,
    'Location: ' + [row.district, row.city].filter(Boolean).join(', '),
    'Price Range: ' + priceRange,
    row.description_en ? 'About: ' + row.description_en.substring(0, 400) : '',
    'Available Unit Types:',
    layoutLines,
    '======================================',
  ].filter(Boolean).join('\n');
}

// ── Compose full system prompt ──
const systemPrompt = `You are Sara, a professional real estate consultant at Tamleeq.
You are making an outbound call to follow up on a property inquiry the lead submitted via an online advertisement.

${propertyContext}

STRICT RULES:
1. You are calling ONLY about "${propertyName}". Do not discuss or quote other properties.
2. If the lead asks about a different property, say: "I would be happy to have a specialist contact you about that separately. Today I am calling specifically about ${propertyName}."
3. Do not fabricate any prices, areas, or details not listed above.
4. Keep the call friendly, professional, and under 5 minutes.
5. If the lead says it is a bad time, say: "No problem, when is a good time for us to call back?" and note the time.
6. Speak naturally — this is a phone call, not a form. Do not read out lists.

QUALIFICATION FLOW — cover these in natural conversation:
Step 1 — Confirm interest: "I am calling about ${propertyName}. Are you still interested in learning more?"
Step 2 — Budget: "What is the budget range you have in mind for this purchase?"
Step 3 — Purpose: "Is this for personal living or as an investment property?"
Step 4 — Timeline: "When are you ideally looking to make a purchase?"
Step 5 — Decision: "Are you the main decision maker, or will family members also be involved?"

QUALIFICATION CRITERIA:
- QUALIFIED: Confirmed interest, budget is realistic relative to ${priceRange}, timeline within 12 months
- NOT_INTERESTED: Lead explicitly says not interested or already purchased elsewhere
- NO_BUDGET_MATCH: Lead's stated budget is significantly below the property price range
- CALLBACK_NEEDED: Lead is interested but unavailable right now or needs to check with family
- NO_ANSWER: Lead did not pick up (this is set by the system, not you)

CLOSING THE CALL:
Always end with: "Thank you for your time, ${input.leadName}. One of our property specialists will be in touch with you very soon with more information."

IMPORTANT — LAST LINE OF YOUR RESPONSE:
After the closing, output exactly one line in this format:
OUTCOME: [QUALIFIED / NOT_INTERESTED / NO_BUDGET_MATCH / CALLBACK_NEEDED]

Example final line: OUTCOME: QUALIFIED`;

return [{
  json: {
    ...input,
    systemPrompt,
    propertyName,
    priceRange,
    propertyCity,
    adType,
    entityUuid: input.entityUuid
  }
}];

