const body = $input.first().json.body || $input.first().json;

// VAPI end-of-call-report structure
const call         = body.call || body;
const callId       = call.id              || '';
const callStatus   = call.status          || '';
const endedReason  = call.endedReason     || '';
const transcript   = body.transcript      || call.transcript  || '';
const summary      = body.summary         || body.analysis?.summary || '';
const recordingUrl = body.recordingUrl    || call.recordingUrl || '';
const duration     = (call.startedAt && call.endedAt)
  ? Math.round((new Date(call.endedAt) - new Date(call.startedAt)) / 1000)
  : 0;

// Pull metadata we stored on call creation
const meta        = call.metadata        || body.metadata || {};
const crmLeadId   = meta.crm_lead_id     || '';
const adType      = meta.ad_type         || '';
const entityUuid  = meta.entity_uuid     || '';
const retryCount  = parseInt(meta.retry_count || '0');

// ── Determine outcome ──
let outcome = 'UNKNOWN';
const haystack = (summary + ' ' + transcript + ' ' + endedReason).toUpperCase();

const noAnswerReasons = [
  'customer-did-not-answer', 'no-answer', 'voicemail',
  'machine-detected', 'machine_end_other'
];
if (noAnswerReasons.includes(endedReason.toLowerCase())) {
  outcome = 'NO_ANSWER';
} else if (haystack.includes('OUTCOME: QUALIFIED')) {
  outcome = 'QUALIFIED';
} else if (haystack.includes('OUTCOME: NOT_INTERESTED')) {
  outcome = 'NOT_INTERESTED';
} else if (haystack.includes('OUTCOME: NO_BUDGET_MATCH')) {
  outcome = 'NO_BUDGET_MATCH';
} else if (haystack.includes('OUTCOME: CALLBACK_NEEDED')) {
  outcome = 'CALLBACK_NEEDED';
} else if (callStatus === 'ended' || callStatus === 'completed') {
  outcome = 'COMPLETED_UNKNOWN';
}

// ── Try to extract budget amount from transcript ──
const budgetMatch = transcript.match(/(SAR\s*)?([\d,\.]+)\s*(million|M|K|SAR)/i);
const mentionedBudget = budgetMatch ? budgetMatch[0].trim() : null;

// ── Truncate transcript to avoid DB overflow ──
const transcriptShort = transcript.substring(0, 3000);

return [{
  json: {
    callId, callStatus, endedReason, transcript: transcriptShort,
    summary, recordingUrl, duration,
    crmLeadId, adType, entityUuid, retryCount,
    outcome, mentionedBudget
  }
}];

const data  = $input.first().json;
const retry = data.retryCount || 0;

if (retry < 2) {
  const delayHours = retry === 0 ? 2 : 24;
  return [{
    json: {
      ...data,
      action:         'RETRY',
      nextRetryCount: retry + 1,
      delayHours,
      scheduledAt: new Date(Date.now() + delayHours * 3_600_000).toISOString()
    }
  }];
}
return [{
  json: {
    ...data,
    action: 'COLD',
    reason: 'No answer after 3 VAPI call attempts'
  }
}];
